import { z } from 'zod';

export const limits = {
  url: 4096,
  title: 300,
  description: 2000,
  notes: 10_000,
  tag: 100,
  query: 1000,
} as const;

const nullableLimitedText = (max: number) => z.string().max(max).nullable();
export const HttpUrlSchema = z
  .string()
  .max(limits.url)
  .url()
  .refine((value) => ['http:', 'https:'].includes(new URL(value).protocol), 'Use an HTTP or HTTPS URL');
export const TagNameSchema = z.string().trim().min(1).max(limits.tag);

export const BookmarkSchema = z
  .object({
    id: z.uuid(),
    url: HttpUrlSchema,
    title: z.string().trim().min(1).max(limits.title),
    description: nullableLimitedText(limits.description),
    iconUrl: z.string().nullable(),
    notes: nullableLimitedText(limits.notes),
    tags: z.array(TagNameSchema),
    readLater: z.boolean(),
    isRead: z.boolean(),
    createdAt: z.iso.datetime(),
    updatedAt: z.iso.datetime(),
  })
  .refine(({ readLater, isRead }) => readLater || !isRead, {
    message: 'A bookmark outside read later cannot be read',
    path: ['isRead'],
  });

export const BookmarkInputSchema = z.object({
  url: HttpUrlSchema,
  title: z.string().trim().min(1).max(limits.title),
  description: nullableLimitedText(limits.description).optional().default(null),
  iconToken: z.string().nullable().optional().default(null),
  notes: nullableLimitedText(limits.notes).optional().default(null),
  tags: z.array(TagNameSchema).default([]),
  readLater: z.boolean().default(false),
});

export const BookmarkPatchSchema = BookmarkInputSchema.partial().refine(
  (value) => Object.keys(value).length > 0,
  'Supply at least one field',
);

export const ReadingStateInputSchema = z
  .object({ readLater: z.boolean(), isRead: z.boolean() })
  .refine(({ readLater, isRead }) => readLater || !isRead, {
    message: 'isRead must be false when readLater is false',
    path: ['isRead'],
  });

export const MetadataFieldStatusSchema = z.enum(['found', 'missing', 'invalid', 'fetch_failed']);
export const MetadataFieldSchema = z.object({
  status: MetadataFieldStatusSchema,
  value: z.string().nullable().optional(),
  source: z.string().nullable().optional(),
});
export const MetadataPreviewSchema = z.object({
  requestedUrl: HttpUrlSchema,
  finalUrl: HttpUrlSchema.nullable(),
  outcome: z.enum(['complete', 'partial', 'failed']),
  fields: z.object({
    title: MetadataFieldSchema,
    description: MetadataFieldSchema,
    icon: MetadataFieldSchema,
  }),
  iconToken: z.string().nullable().optional(),
  warnings: z.array(z.string()),
});

export const QuerySummarySchema = z.object({
  raw: z.string().max(limits.query),
  ast: z.record(z.string(), z.unknown()),
  labels: z.array(z.string()),
});
export const TagSummarySchema = z.object({ name: TagNameSchema, bookmarkCount: z.number().int().nonnegative() });

export const ApiErrorSchema = z.object({
  code: z.string(),
  message: z.string(),
  fieldErrors: z.record(z.string(), z.array(z.string())).optional(),
  existingId: z.uuid().optional(),
  span: z.object({ start: z.number().int().nonnegative(), end: z.number().int().nonnegative() }).optional(),
});
export const ErrorEnvelopeSchema = z.object({ error: ApiErrorSchema });
export const successEnvelope = <T extends z.ZodType>(schema: T) => z.object({ data: schema });
export const BookmarkEnvelopeSchema = successEnvelope(BookmarkSchema);
export const MetadataPreviewEnvelopeSchema = successEnvelope(MetadataPreviewSchema);

export type Bookmark = z.infer<typeof BookmarkSchema>;
export type BookmarkInput = z.infer<typeof BookmarkInputSchema>;
export type BookmarkPatch = z.infer<typeof BookmarkPatchSchema>;
export type ReadingStateInput = z.infer<typeof ReadingStateInputSchema>;
export type MetadataPreview = z.infer<typeof MetadataPreviewSchema>;
export type QuerySummary = z.infer<typeof QuerySummarySchema>;
export type TagSummary = z.infer<typeof TagSummarySchema>;
export type ApiError = z.infer<typeof ApiErrorSchema>;
export type ErrorEnvelope = z.infer<typeof ErrorEnvelopeSchema>;
export type SuccessEnvelope<T> = { data: T };
import path from 'node:path';
import { z } from 'zod';

const EnvironmentSchema = z.object({
  HOST: z.literal('0.0.0.0').default('0.0.0.0'),
  PORT: z.coerce.number().int().min(1).max(65_535).default(4000),
  DATABASE_PATH: z.string().min(1).default(path.resolve('data/bookmarks.sqlite')),
  ICON_CACHE_PATH: z.string().min(1).default(path.resolve('data/icons')),
  METADATA_TIMEOUT_MS: z.coerce.number().int().positive().max(5_000).default(5_000),
  METADATA_HTML_MAX_BYTES: z.coerce.number().int().positive().max(1_048_576).default(1_048_576),
  METADATA_ICON_MAX_BYTES: z.coerce.number().int().positive().max(262_144).default(262_144),
  METADATA_MAX_REDIRECTS: z.coerce.number().int().min(0).max(5).default(5),
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
});

export type AppConfig = z.infer<typeof EnvironmentSchema>;

export function loadConfig(environment: NodeJS.ProcessEnv = process.env): AppConfig {
  return EnvironmentSchema.parse(environment);
}
import { normalizeTagValue, type SearchAst } from '../../shared/search/ast.js';

export type BookmarkSort = 'createdAt' | 'title';
export type SortOrder = 'asc' | 'desc';
export type BookmarkScope = 'all' | 'unread-read-later';

export type SearchCompileInput = {
  ast: SearchAst;
  selectedTags?: string[];
  scope?: BookmarkScope;
  sort?: BookmarkSort;
  order?: SortOrder;
};

export type CompiledBookmarkQuery = {
  where: string;
  parameters: unknown[];
  orderBy: string;
};

const SORT_COLUMNS: Record<BookmarkSort, string> = {
  createdAt: 'b.created_at',
  title: 'b.title COLLATE NOCASE',
};

function escapeLike(value: string): string {
  return value.replace(/\\/gu, '\\\\').replace(/%/gu, '\\%').replace(/_/gu, '\\_');
}

export function compileBookmarkQuery(input: SearchCompileInput): CompiledBookmarkQuery {
  const predicates: string[] = [];
  const parameters: unknown[] = [];

  for (const clause of input.ast.clauses) {
    if (clause.type === 'text') {
      const pattern = `%${escapeLike(clause.value)}%`;
      predicates.push(`(
        lower(b.title) LIKE ? ESCAPE '\\'
        OR lower(b.url) LIKE ? ESCAPE '\\'
        OR lower(coalesce(b.description, '')) LIKE ? ESCAPE '\\'
        OR lower(coalesce(b.notes, '')) LIKE ? ESCAPE '\\'
        OR EXISTS (
          SELECT 1 FROM bookmark_tags search_bt
          JOIN tags search_t ON search_t.id = search_bt.tag_id
          WHERE search_bt.bookmark_id = b.id
            AND search_t.normalized_name LIKE ? ESCAPE '\\'
        )
      )`);
      parameters.push(pattern, pattern, pattern, pattern, pattern);
    } else {
      predicates.push(`EXISTS (
        SELECT 1 FROM bookmark_tags query_bt
        JOIN tags query_t ON query_t.id = query_bt.tag_id
        WHERE query_bt.bookmark_id = b.id
          AND query_t.normalized_name IN (${clause.values.map(() => '?').join(', ')})
      )`);
      parameters.push(...clause.values);
    }
  }

  for (const selectedTag of [...new Set((input.selectedTags ?? []).map(normalizeTagValue).filter(Boolean))]) {
    predicates.push(`EXISTS (
      SELECT 1 FROM bookmark_tags filter_bt
      JOIN tags filter_t ON filter_t.id = filter_bt.tag_id
      WHERE filter_bt.bookmark_id = b.id AND filter_t.normalized_name = ?
    )`);
    parameters.push(selectedTag);
  }

  if ((input.scope ?? 'all') === 'unread-read-later') {
    predicates.push('b.read_later = 1 AND b.is_read = 0');
  }

  const sort = input.sort ?? 'createdAt';
  const order = input.order ?? 'desc';
  if (!(sort in SORT_COLUMNS)) throw new TypeError(`Unsupported bookmark sort: ${String(sort)}`);
  if (order !== 'asc' && order !== 'desc') throw new TypeError(`Unsupported sort order: ${String(order)}`);
  const direction = order.toUpperCase();
  const tieBreaker = sort === 'createdAt' ? `b.id ${direction}` : `b.created_at DESC, b.id ASC`;

  return {
    where: predicates.length ? predicates.join('\nAND ') : '1 = 1',
    parameters,
    orderBy: `${SORT_COLUMNS[sort]} ${direction}, ${tieBreaker}`,
  };
}
export const MAX_SEARCH_QUERY_LENGTH = 1_000;
export const MAX_SEARCH_CLAUSES = 50;

export type TextClause = {
  type: 'text';
  value: string;
  exact: boolean;
};

export type TagAnyClause = {
  type: 'tagAny';
  values: string[];
};

export type SearchClause = TextClause | TagAnyClause;

export type SearchAst = {
  type: 'and';
  clauses: SearchClause[];
};

export type SearchParseErrorCode =
  | 'UNCLOSED_QUOTE'
  | 'EMPTY_TAG'
  | 'EMPTY_GROUP'
  | 'MISSING_ALTERNATIVE'
  | 'UNEXPECTED_RPAREN'
  | 'INVALID_ESCAPE'
  | 'QUERY_TOO_LONG'
  | 'TOO_MANY_CLAUSES';

export type CharacterSpan = { start: number; end: number };

const ERROR_MESSAGES: Record<SearchParseErrorCode, string> = {
  UNCLOSED_QUOTE: 'Close the quoted phrase with a double quote.',
  EMPTY_TAG: 'Enter a tag after tag:.',
  EMPTY_GROUP: 'Add at least one tag inside the group.',
  MISSING_ALTERNATIVE: 'Enter a tag on both sides of |.',
  UNEXPECTED_RPAREN: 'Remove the unexpected closing parenthesis.',
  INVALID_ESCAPE: 'Only reserved punctuation can be escaped.',
  QUERY_TOO_LONG: `Search queries can contain at most ${MAX_SEARCH_QUERY_LENGTH} characters.`,
  TOO_MANY_CLAUSES: `Search queries can contain at most ${MAX_SEARCH_CLAUSES} conditions.`,
};

export class SearchParseError extends Error {
  readonly code: SearchParseErrorCode;
  readonly span: CharacterSpan;

  constructor(code: SearchParseErrorCode, span: CharacterSpan, message = ERROR_MESSAGES[code]) {
    super(message);
    this.name = 'SearchParseError';
    this.code = code;
    this.span = span;
  }

  toJSON() {
    return { code: this.code, message: this.message, span: this.span };
  }
}

export function normalizeSearchText(value: string): string {
  return value.normalize('NFKC').toLocaleLowerCase('und');
}

export function normalizeTagValue(value: string): string {
  return normalizeSearchText(value).trim().replace(/\s+/gu, ' ');
}

