const EnvironmentSchema = z.object({
  HOST: z.literal('0.0.0.0').default('0.0.0.0'),
  PORT: z.coerce.number().int().min(1).max(65_535).default(4000),
  DATABASE_PATH: z.string().min(1).default(path.resolve('data/bookmarks.sqlite')),
