  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
});

export type AppConfig = z.infer<typeof EnvironmentSchema>;

export function loadConfig(environment: NodeJS.ProcessEnv = process.env): AppConfig {
  return EnvironmentSchema.parse(environment);
}
import { normalizeTagValue, type SearchAst } from '../../shared/search/ast.js';

export type BookmarkSort = 'createdAt' | 'title';
export type SortOrder = 'asc' | 'desc';
export type BookmarkScope = 'all' | 'unread-read-later';

export type SearchCompileInput = {
  ast: SearchAst;
  selectedTags?: string[];
  scope?: BookmarkScope;
  sort?: BookmarkSort;
  order?: SortOrder;
};

export type CompiledBookmarkQuery = {
  where: string;
  parameters: unknown[];
  orderBy: string;
};

const SORT_COLUMNS: Record<BookmarkSort, string> = {
  createdAt: 'b.created_at',
  title: 'b.title COLLATE NOCASE',
};

function escapeLike(value: string): string {
  return value.replace(/\\/gu, '\\\\').replace(/%/gu, '\\%').replace(/_/gu, '\\_');
}

export function compileBookmarkQuery(input: SearchCompileInput): CompiledBookmarkQuery {
  const predicates: string[] = [];
  const parameters: unknown[] = [];

  for (const clause of input.ast.clauses) {
    if (clause.type === 'text') {
      const pattern = `%${escapeLike(clause.value)}%`;
      predicates.push(`(
        lower(b.title) LIKE ? ESCAPE '\\'
        OR lower(b.url) LIKE ? ESCAPE '\\'
        OR lower(coalesce(b.description, '')) LIKE ? ESCAPE '\\'
        OR lower(coalesce(b.notes, '')) LIKE ? ESCAPE '\\'
        OR EXISTS (
          SELECT 1 FROM bookmark_tags search_bt
          JOIN tags search_t ON search_t.id = search_bt.tag_id
          WHERE search_bt.bookmark_id = b.id
            AND search_t.normalized_name LIKE ? ESCAPE '\\'
        )
      )`);
      parameters.push(pattern, pattern, pattern, pattern, pattern);
    } else {
      predicates.push(`EXISTS (
        SELECT 1 FROM bookmark_tags query_bt
        JOIN tags query_t ON query_t.id = query_bt.tag_id
        WHERE query_bt.bookmark_id = b.id
          AND query_t.normalized_name IN (${clause.values.map(() => '?').join(', ')})
      )`);
      parameters.push(...clause.values);
    }
  }

  for (const selectedTag of [...new Set((input.selectedTags ?? []).map(normalizeTagValue).filter(Boolean))]) {
    predicates.push(`EXISTS (
      SELECT 1 FROM bookmark_tags filter_bt
      JOIN tags filter_t ON filter_t.id = filter_bt.tag_id
      WHERE filter_bt.bookmark_id = b.id AND filter_t.normalized_name = ?
    )`);
    parameters.push(selectedTag);
  }

  if ((input.scope ?? 'all') === 'unread-read-later') {
    predicates.push('b.read_later = 1 AND b.is_read = 0');
  }

  const sort = input.sort ?? 'createdAt';
  const order = input.order ?? 'desc';
  if (!(sort in SORT_COLUMNS)) throw new TypeError(`Unsupported bookmark sort: ${String(sort)}`);
  if (order !== 'asc' && order !== 'desc') throw new TypeError(`Unsupported sort order: ${String(order)}`);
  const direction = order.toUpperCase();
  const tieBreaker = sort === 'createdAt' ? `b.id ${direction}` : `b.created_at DESC, b.id ASC`;

  return {
    where: predicates.length ? predicates.join('\nAND ') : '1 = 1',
    parameters,
    orderBy: `${SORT_COLUMNS[sort]} ${direction}, ${tieBreaker}`,
  };
}
export const MAX_SEARCH_QUERY_LENGTH = 1_000;
export const MAX_SEARCH_CLAUSES = 50;

export type TextClause = {
  type: 'text';
  value: string;
  exact: boolean;
};

export type TagAnyClause = {
  type: 'tagAny';
  values: string[];
};

export type SearchClause = TextClause | TagAnyClause;

export type SearchAst = {
  type: 'and';
  clauses: SearchClause[];
};

export type SearchParseErrorCode =
  | 'UNCLOSED_QUOTE'
  | 'EMPTY_TAG'
  | 'EMPTY_GROUP'
  | 'MISSING_ALTERNATIVE'
  | 'UNEXPECTED_RPAREN'
  | 'INVALID_ESCAPE'
  | 'QUERY_TOO_LONG'
  | 'TOO_MANY_CLAUSES';

export type CharacterSpan = { start: number; end: number };

const ERROR_MESSAGES: Record<SearchParseErrorCode, string> = {
  UNCLOSED_QUOTE: 'Close the quoted phrase with a double quote.',
  EMPTY_TAG: 'Enter a tag after tag:.',
  EMPTY_GROUP: 'Add at least one tag inside the group.',
  MISSING_ALTERNATIVE: 'Enter a tag on both sides of |.',
  UNEXPECTED_RPAREN: 'Remove the unexpected closing parenthesis.',
  INVALID_ESCAPE: 'Only reserved punctuation can be escaped.',
  QUERY_TOO_LONG: `Search queries can contain at most ${MAX_SEARCH_QUERY_LENGTH} characters.`,
  TOO_MANY_CLAUSES: `Search queries can contain at most ${MAX_SEARCH_CLAUSES} conditions.`,
};

export class SearchParseError extends Error {
  readonly code: SearchParseErrorCode;
  readonly span: CharacterSpan;

  constructor(code: SearchParseErrorCode, span: CharacterSpan, message = ERROR_MESSAGES[code]) {
    super(message);
    this.name = 'SearchParseError';
    this.code = code;
    this.span = span;
  }

  toJSON() {
    return { code: this.code, message: this.message, span: this.span };
  }
}

export function normalizeSearchText(value: string): string {
  return value.normalize('NFKC').toLocaleLowerCase('und');
}

export function normalizeTagValue(value: string): string {
  return normalizeSearchText(value).trim().replace(/\s+/gu, ' ');
}

