import { Component, type ErrorInfo, type ReactNode, useState } from 'react';
import './styles/global.css';
import './styles/library.css';
import { BookmarksView } from './features/bookmarks/BookmarksView';

type View = 'library' | 'read-later';

interface ErrorBoundaryState {
  failed: boolean;
}

class ErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
  state: ErrorBoundaryState = { failed: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { failed: true };
  }

  componentDidCatch(error: Error, details: ErrorInfo): void {
    console.error('The application view failed', error, details.componentStack);
  }

  render(): ReactNode {
    if (this.state.failed) {
      return (
        <main className="shell shell--message">
          <h1>Bookmarks</h1>
          <p role="alert">The library could not be displayed. Reload the page to try again.</p>
        </main>
      );
    }
    return this.props.children;
  }
}

function ApplicationShell() {
  const [view, setView] = useState<View>('library');
  const [unreadCount, setUnreadCount] = useState(0);
  const [announcement, setAnnouncement] = useState('');

  return (
    <div className="app" data-harness-ready="true">
      <header className="masthead">
        <a
          className="brand"
          href="/"
          onClick={(event) => {
            event.preventDefault();
            setView('library');
          }}
        >
          Keepsake
        </a>
        <nav aria-label="Primary navigation">
          <button
            aria-current={view === 'library' ? 'page' : undefined}
            onClick={() => setView('library')}
          >
            Library
          </button>
          <button
            aria-current={view === 'read-later' ? 'page' : undefined}
            onClick={() => setView('read-later')}
          >
            Read later{' '}
            {unreadCount > 0 && (
              <span className="nav-count" aria-label={`${unreadCount} unread`}>
                {unreadCount}
              </span>
            )}
          </button>
        </nav>
      </header>
      <main className="shell" id="main-content">
        <p className="eyebrow">Personal bookmark manager</p>
        <h1>{view === 'library' ? 'Your library' : 'Read later'}</h1>
        <p className="lede">
          {view === 'library'
            ? 'Save the useful corners of the web and find them again.'
            : 'A quiet queue for the things you want to return to.'}
        </p>
        <BookmarksView
          scope={view === 'library' ? 'all' : 'unread-read-later'}
          onUnreadCountChange={view === 'library' ? setUnreadCount : undefined}
          announce={setAnnouncement}
        />
      </main>
      <div
        className="sr-only"
        aria-live="polite"
        aria-atomic="true"
        role="status"
        id="operation-status"
      >
        {announcement}
      </div>
    </div>
  );
}

export function App() {
  return (
    <ErrorBoundary>
      <ApplicationShell />
    </ErrorBoundary>
  );
}
import { useCallback, useEffect, useState } from 'react';
import { SaveBookmarkForm } from './SaveBookmarkForm';
import { BookmarkLibrary } from './BookmarkLibrary';
import { EditBookmarkForm } from './EditBookmarkForm';
import { DeleteBookmarkDialog } from './DeleteBookmarkDialog';
import { SearchBar } from '../search/SearchBar';
import { LibraryControls, type TagOption } from '../search/LibraryControls';
import type { ApiError, Bookmark, BookmarkDraft, SortField, SortOrder } from './types';

interface Props {
  scope?: 'all' | 'unread-read-later';
  onUnreadCountChange?: (count: number) => void;
  announce?: (message: string) => void;
}
async function decode<T>(response: Response): Promise<T> {
  const body =
    response.status === 204 ? {} : ((await response.json()) as { data?: T; error?: ApiError });
  if (!response.ok) {
    const error = (body as { error?: ApiError }).error;
    const thrown = new Error(error?.message ?? 'The request did not complete.') as Error & {
      details?: ApiError;
    };
    thrown.details = error;
    throw thrown;
  }
  return (body as { data: T }).data;
}

export function BookmarksView({ scope = 'all', onUnreadCountChange, announce }: Props) {
  const [items, setItems] = useState<Bookmark[]>([]),
    [tags, setTags] = useState<TagOption[]>([]),
    [query, setQuery] = useState(''),
    [labels, setLabels] = useState<string[]>([]),
    [selectedTags, setSelectedTags] = useState<string[]>([]),
    [sort, setSort] = useState<SortField>('createdAt'),
    [order, setOrder] = useState<SortOrder>('desc'),
    [loading, setLoading] = useState(true),
    [saving, setSaving] = useState(false),
    [error, setError] = useState<string | null>(null),
    [searchError, setSearchError] = useState<{
      message: string;
      span?: { start: number; end: number };
    } | null>(null),
    [editing, setEditing] = useState<Bookmark | null>(null),
    [deleting, setDeleting] = useState<Bookmark | null>(null);
  const [deleteTrigger, setDeleteTrigger] = useState<HTMLButtonElement | null>(null);
  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    setSearchError(null);
    const params = new URLSearchParams({ scope, sort, order });
    if (query) params.set('q', query);
    selectedTags.forEach((tag) => params.append('tag', tag));
    try {
      const result = await decode<{ items: Bookmark[]; query: { labels: string[] } }>(
        await fetch(`/api/bookmarks?${params}`),
      );
      setItems(result.items);
      setLabels(result.query.labels);
      onUnreadCountChange?.(result.items.filter((item) => item.readLater && !item.isRead).length);
    } catch (reason) {
      const failure = reason as Error & { details?: ApiError };
      if (failure.details?.span)
        setSearchError({ message: failure.message, span: failure.details.span });
      else setError(failure.message);
    } finally {
      setLoading(false);
    }
  }, [scope, sort, order, query, selectedTags, onUnreadCountChange]);
  useEffect(() => {
    const timer = window.setTimeout(() => void load(), 0);
    return () => window.clearTimeout(timer);
  }, [load]);
  useEffect(() => {
    void fetch('/api/tags')
      .then((response) => decode<Array<TagOption & { bookmarkCount?: number }>>(response))
      .then((values) =>
        setTags(
          values.map((tag) => ({ name: tag.name, count: tag.count ?? tag.bookmarkCount ?? 0 })),
        ),
      )
      .catch(() => setTags([]));
  }, [items.length]);
  useEffect(() => {
    const params = new URLSearchParams();
    if (query) params.set('q', query);
    selectedTags.forEach((tag) => params.append('tag', tag));
    if (sort !== 'createdAt') params.set('sort', sort);
    if (order !== 'desc') params.set('order', order);
    window.history.replaceState(
      null,
      '',
      `${window.location.pathname}${params.size ? `?${params}` : ''}`,
    );
  }, [query, selectedTags, sort, order]);
  async function save(draft: BookmarkDraft) {
    setSaving(true);
    try {
      const created = await decode<Bookmark>(
        await fetch('/api/bookmarks', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
