import type { Bookmark } from './types';
import { ReadingStatusControls } from '../read-later/ReadingStatusControls';

interface Props {
  bookmark: Bookmark;
  onReadingChange: (bookmark: Bookmark, readLater: boolean, isRead: boolean) => Promise<void>;
  onEdit: (bookmark: Bookmark) => void;
  onDelete: (bookmark: Bookmark, trigger: HTMLButtonElement) => void;
}
export function BookmarkCard({ bookmark, onReadingChange, onEdit, onDelete }: Props) {
  let hostname = bookmark.url;
  try {
    hostname = new URL(bookmark.url).hostname;
  } catch {
    /* display original */
  }
  return (
    <article className="bookmark-card" id={`bookmark-${bookmark.id}`} tabIndex={-1}>
      <div className="bookmark-main">
        <div className="site-icon" aria-hidden="true">
          {bookmark.iconUrl ? (
            <img src={bookmark.iconUrl} alt="" />
          ) : (
            hostname.slice(0, 1).toUpperCase()
          )}
        </div>
        <div className="bookmark-copy">
          <div className="bookmark-title-row">
            <h3>
              <a href={bookmark.url} target="_blank" rel="noopener noreferrer">
                {bookmark.title}
                <span className="external-mark" aria-label="opens in a new tab">
                  ↗
                </span>
              </a>
            </h3>
            {bookmark.readLater && (
              <span className={`status-badge ${bookmark.isRead ? 'read' : ''}`}>
                {bookmark.isRead ? 'Read' : 'Unread'}
              </span>
            )}
          </div>
          <p className="bookmark-url">{hostname}</p>
          {bookmark.description && <p className="bookmark-description">{bookmark.description}</p>}
          {bookmark.notes && (
            <p className="bookmark-notes">
              <span>Note</span> {bookmark.notes}
            </p>
          )}
          <div className="tag-list" aria-label="Tags">
            {bookmark.tags.map((tag) => (
              <span className="tag" key={tag}>
                {tag}
              </span>
            ))}
          </div>
        </div>
      </div>
      <footer>
        <time dateTime={bookmark.createdAt}>
          Saved{' '}
          {new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(
            new Date(bookmark.createdAt),
          )}
        </time>
        <div className="card-actions">
          <ReadingStatusControls
            bookmark={bookmark}
            onChange={(readLater, isRead) => onReadingChange(bookmark, readLater, isRead)}
          />
          <button
            className="button icon-button"
            aria-label={`Edit ${bookmark.title}`}
            onClick={() => onEdit(bookmark)}
          >
            Edit
          </button>
          <button
            className="button icon-button danger-text"
            aria-label={`Delete ${bookmark.title}`}
            onClick={(e) => onDelete(bookmark, e.currentTarget)}
          >
            Delete
          </button>
        </div>
      </footer>
    </article>
  );
}
import { useState } from 'react';
import type { Bookmark } from '../bookmarks/types';

interface Props {
  bookmark: Bookmark;
  onChange: (readLater: boolean, isRead: boolean) => Promise<void>;
}
export function ReadingStatusControls({ bookmark, onChange }: Props) {
  const [pending, setPending] = useState(false);
  async function update(readLater: boolean, isRead: boolean) {
    setPending(true);
    try {
      await onChange(readLater, isRead);
    } finally {
      setPending(false);
    }
  }
  return (
    <div className="reading-controls" aria-label={`Reading status for ${bookmark.title}`}>
      {!bookmark.readLater ? (
        <button
          className="button subtle compact"
          disabled={pending}
          onClick={() => void update(true, false)}
        >
          ＋ Read later
        </button>
      ) : (
        <>
          <button
            className="button subtle compact"
            disabled={pending}
            onClick={() => void update(true, !bookmark.isRead)}
          >
            {bookmark.isRead ? 'Mark unread' : '✓ Mark read'}
          </button>
          <button
            className="text-button"
            disabled={pending}
            onClick={() => void update(false, false)}
          >
            Remove from list
          </button>
        </>
      )}
    </div>
  );
}
import { useEffect, useRef, useState } from 'react';
import type { Bookmark } from './types';

interface Props {
  bookmark: Bookmark | null;
  returnFocus?: HTMLButtonElement | null;
  onCancel: () => void;
  onConfirm: (bookmark: Bookmark) => Promise<void>;
}
export function DeleteBookmarkDialog({ bookmark, returnFocus, onCancel, onConfirm }: Props) {
  const dialog = useRef<HTMLDialogElement>(null),
    cancel = useRef<HTMLButtonElement>(null);
  const [pending, setPending] = useState(false),
    [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (bookmark) {
      dialog.current?.showModal();
      cancel.current?.focus();
    } else dialog.current?.close();
  }, [bookmark]);
  function close() {
    onCancel();
    window.setTimeout(() => returnFocus?.focus(), 0);
  }
  async function confirm() {
    if (!bookmark) return;
    setPending(true);
    setError(null);
    try {
      await onConfirm(bookmark);
      onCancel();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'The bookmark could not be deleted.');
      setPending(false);
    }
  }
  return (
    <dialog
      className="confirm-dialog"
      ref={dialog}
      onCancel={(e) => {
        e.preventDefault();
        if (!pending) close();
      }}
      onClose={() => returnFocus?.focus()}
    >
      <div className="danger-glyph" aria-hidden="true">
        !
      </div>
      <h2>Delete this bookmark?</h2>
      <p>
        <strong>{bookmark?.title}</strong> will be permanently removed. This can’t be undone.
      </p>
      {error && (
        <p className="inline-error" role="alert">
          {error}
        </p>
      )}
      <div className="dialog-actions">
        <button ref={cancel} className="button ghost" disabled={pending} onClick={close}>
          Keep bookmark
        </button>
        <button className="button danger" disabled={pending} onClick={() => void confirm()}>
          {pending ? 'Deleting…' : 'Delete permanently'}
        </button>
      </div>
    </dialog>
  );
}

